def solve(inputs: dict) -> float:
    rem = inputs['REMAINDERS']
    mod = inputs['MODULI']
    x = 0
    M = 1
    for m in mod:
        M *= m
    for r, m in zip(rem, mod):
        Mi = M // m
        # modular inverse via pow
        inv = pow(Mi % m, -1, m)
        x = (x + r * Mi * inv) % M
    return float(x)
